import * as React from "react";
import { Page, BlockStack, Grid, Banner } from "@xco-agency/corex-ui";
import { MOCK_INTEGRATIONS, MOCK_WEBHOOK_LOGS } from "../constants";
import { IntegrationCard } from "../partials/IntegrationCard";
import { IntegrationCategoryTabs } from "../partials/IntegrationCategoryTabs";
import { IntegrationConfigModal } from "../partials/IntegrationConfigModal";
import { WebhookLogCard } from "../partials/WebhookLogCard";
import type {
  IntegrationCategoryType,
  IntegrationItemType,
  WebhookLogItemType,
} from "../types";

export function IntegrationsHubExample() {
  const [integrations, setIntegrations] =
    React.useState<IntegrationItemType[]>(MOCK_INTEGRATIONS);
  const [logs, setLogs] =
    React.useState<WebhookLogItemType[]>(MOCK_WEBHOOK_LOGS);
  const [selectedCategory, setSelectedCategory] =
    React.useState<IntegrationCategoryType>("all");
  const [activeConfigIntegration, setActiveConfigIntegration] =
    React.useState<IntegrationItemType | null>(null);
  const [toastMessage, setToastMessage] = React.useState<string | null>(null);

  const categories = React.useMemo(() => {
    return [
      {
        id: "all" as IntegrationCategoryType,
        label: "All Services",
        count: integrations.length,
      },
      {
        id: "marketing" as IntegrationCategoryType,
        label: "Marketing",
        count: integrations.filter((i) => i.category === "marketing").length,
      },
      {
        id: "support" as IntegrationCategoryType,
        label: "Customer Support",
        count: integrations.filter((i) => i.category === "support").length,
      },
      {
        id: "analytics" as IntegrationCategoryType,
        label: "Analytics",
        count: integrations.filter((i) => i.category === "analytics").length,
      },
      {
        id: "webhooks" as IntegrationCategoryType,
        label: "Custom Webhooks",
        count: integrations.filter((i) => i.category === "webhooks").length,
      },
    ];
  }, [integrations]);

  const filteredIntegrations = React.useMemo(() => {
    if (selectedCategory === "all") return integrations;
    return integrations.filter((i) => i.category === selectedCategory);
  }, [integrations, selectedCategory]);

  const handleToggleSync = (id: string, enabled: boolean) => {
    setIntegrations((prev) =>
      prev.map((item) =>
        item.id === id ? { ...item, syncEnabled: enabled } : item,
      ),
    );
  };

  const handleSaveConfig = (
    id: string,
    config: { apiKey?: string; webhookUrl?: string },
  ) => {
    setIntegrations((prev) =>
      prev.map((item) =>
        item.id === id
          ? {
              ...item,
              ...config,
              status: "connected",
              syncEnabled: true,
              lastSyncedAt: "Just now",
            }
          : item,
      ),
    );
    setToastMessage(`Saved configuration for ${id}!`);
  };

  const handleTestConnection = async (_id: string): Promise<boolean> => {
    await new Promise((res) => setTimeout(res, 600));
    return true;
  };

  const handleRefreshLogs = () => {
    const newLog: WebhookLogItemType = {
      id: `log-${Date.now()}`,
      topic: "cart/updated",
      status: "success",
      statusCode: 200,
      timestamp: "Just now",
      durationMs: 94,
    };
    setLogs((prev) => [newLog, ...prev.slice(0, 5)]);
  };

  return (
    <Page
      heading="Integrations & Webhooks"
      subheading="Connect external services to synchronize cart events, customer profiles, and notifications."
      inlineSize="large"
    >
      <BlockStack gap="base">
        {toastMessage && (
          <Banner
            tone="success"
            title={toastMessage}
            onDismiss={() => setToastMessage(null)}
          />
        )}

        {/* Category Tabs */}
        <IntegrationCategoryTabs
          categories={categories}
          selectedCategory={selectedCategory}
          onSelectCategory={setSelectedCategory}
        />

        {/* Integration Cards Grid */}
        <Grid columns={{ xs: 1, sm: 1, md: 2, lg: 3 }} gap="base">
          {filteredIntegrations.map((item) => (
            <IntegrationCard
              key={item.id}
              integration={item}
              onToggleSync={handleToggleSync}
              onConfigure={setActiveConfigIntegration}
            />
          ))}
        </Grid>

        {/* Webhook Delivery Log */}
        <WebhookLogCard logs={logs} onRefresh={handleRefreshLogs} />

        {/* Setup Configuration Modal */}
        <IntegrationConfigModal
          open={activeConfigIntegration !== null}
          integration={activeConfigIntegration}
          onClose={() => setActiveConfigIntegration(null)}
          onSave={handleSaveConfig}
          onTestConnection={handleTestConnection}
        />
      </BlockStack>
    </Page>
  );
}

export * from "./types";
export * from "./constants";
export { IntegrationCategoryTabs } from "./partials/IntegrationCategoryTabs";
export { IntegrationCard } from "./partials/IntegrationCard";
export { IntegrationConfigModal } from "./partials/IntegrationConfigModal";
export { WebhookLogCard } from "./partials/WebhookLogCard";
export { IntegrationsHubExample } from "./examples/IntegrationsHubExample";

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Switch,
  Button,
  IconTile,
  Divider,
} from "@xco-agency/corex-ui";
import type { IntegrationCardPropsType } from "../types";

export function IntegrationCard({
  integration,
  onToggleSync,
  onConfigure,
}: IntegrationCardPropsType) {
  const isConnected = integration.status === "connected";

  return (
    <Card>
      <BlockStack gap="base">
        {/* Top: Icon Tile, Title, Status Badge */}
        <InlineStack
          justifyContent="space-between"
          alignItems="flex-start"
          gap="small-200"
        >
          <InlineStack gap="small-300" alignItems="center">
            <IconTile
              tone={integration.iconTone}
              color="base"
              size="md"
              borderRadius="base"
            >
              <span style={{ fontWeight: 700, fontSize: "14px" }}>
                {integration.name.slice(0, 2).toUpperCase()}
              </span>
            </IconTile>

            <BlockStack gap="none">
              <Text variant="base" heading>
                {integration.name}
              </Text>
              <Text variant="xs" tone="neutral">
                {integration.category.toUpperCase()}
              </Text>
            </BlockStack>
          </InlineStack>

          <Badge tone={isConnected ? "success" : "neutral"}>
            {isConnected ? "Connected" : "Disconnected"}
          </Badge>
        </InlineStack>

        <Text variant="small" tone="neutral">
          {integration.description}
        </Text>

        {isConnected && integration.lastSyncedAt && (
          <Text variant="xs" tone="neutral">
            Last sync: {integration.lastSyncedAt}
          </Text>
        )}
      </BlockStack>

      <BlockStack gap="small" paddingBlockStart="base">
        <Divider />

        <InlineStack justifyContent="space-between" alignItems="center" gap="small-200">
          {isConnected ? (
            <InlineStack gap="small-200" alignItems="center">
              <Switch
                label="Sync events"
                checked={integration.syncEnabled}
                onChange={(checked) => onToggleSync(integration.id, checked)}
              />
              <Text variant="xs" tone="neutral">
                {integration.syncEnabled ? "Syncing active" : "Sync paused"}
              </Text>
            </InlineStack>
          ) : (
            <Text variant="xs" tone="neutral">
              Not configured yet
            </Text>
          )}

          <Button
            variant={isConnected ? "secondary" : "primary"}
            onClick={() => onConfigure(integration)}
          >
            {isConnected ? "Configure" : "Connect"}
          </Button>
        </InlineStack>
      </BlockStack>
    </Card>
  );
}

import * as React from "react";
import { Box, Tabs } from "@xco-agency/corex-ui";
import type { TabItemType } from "@xco-agency/corex-ui";
import type {
  IntegrationCategoryTabsPropsType,
  IntegrationCategoryType,
} from "../types";

export function IntegrationCategoryTabs({
  categories,
  selectedCategory,
  onSelectCategory,
}: IntegrationCategoryTabsPropsType) {
  const tabs: TabItemType<IntegrationCategoryType>[] = categories.map((cat) => ({
    id: cat.id,
    label: cat.label,
    badge: String(cat.count),
  }));

  return (
    <Box paddingInline="base" paddingBlockStart="small-200">
      <Tabs<IntegrationCategoryType>
        tabs={tabs}
        value={selectedCategory}
        onChange={(id) => onSelectCategory(id)}
      />
    </Box>
  );
}

import * as React from "react";
import {
  Modal,
  BlockStack,
  TextField,
  Text,
  Badge,
  InlineStack,
  Button,
} from "@xco-agency/corex-ui";
import type { IntegrationConfigModalPropsType } from "../types";

export function IntegrationConfigModal({
  open,
  integration,
  onClose,
  onSave,
  onTestConnection,
}: IntegrationConfigModalPropsType) {
  const [keyOrUrl, setKeyOrUrl] = React.useState("");
  const [testing, setTesting] = React.useState(false);
  const [testResult, setTestResult] = React.useState<"success" | "error" | null>(null);

  React.useEffect(() => {
    if (integration) {
      setKeyOrUrl(integration.apiKey ?? integration.webhookUrl ?? "");
      setTestResult(null);
    }
  }, [integration]);

  if (!integration) return null;

  const isWebhook = integration.category === "webhooks";

  const handleTest = async () => {
    setTesting(true);
    const ok = await onTestConnection(integration.id);
    setTesting(false);
    setTestResult(ok ? "success" : "error");
  };

  const handleSave = () => {
    if (isWebhook) {
      onSave(integration.id, { webhookUrl: keyOrUrl });
    } else {
      onSave(integration.id, { apiKey: keyOrUrl });
    }
    onClose();
  };

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={`Configure ${integration.name}`}
      primaryAction={{
        content: "Save configuration",
        onAction: handleSave,
      }}
      secondaryActions={[
        {
          content: "Cancel",
          onAction: onClose,
        },
      ]}
    >
      <BlockStack gap="base">
        <Text variant="small" tone="neutral">
          {integration.description}
        </Text>

        <TextField
          label={isWebhook ? "Webhook endpoint URL" : "Private API Key / Token"}
          value={keyOrUrl}
          onChange={(val) => {
            setKeyOrUrl(val);
            setTestResult(null);
          }}
          placeholder={
            isWebhook
              ? "https://api.yourdomain.com/webhooks/orders"
              : "e.g. pk_live_..."
          }
          helpText="Credentials are encrypted at rest using AES-256."
        />

        <InlineStack
          justifyContent="space-between"
          alignItems="center"
          gap="small-200"
        >
          <Button
            variant="secondary"
            loading={testing}
            disabled={!keyOrUrl.trim()}
            onClick={handleTest}
          >
            Test connection
          </Button>

          {testResult === "success" && (
            <Badge tone="success">Connection verified (200 OK)</Badge>
          )}
          {testResult === "error" && (
            <Badge tone="critical">Connection failed (Timed out)</Badge>
          )}
        </InlineStack>
      </BlockStack>
    </Modal>
  );
}

import type * as React from "react";
import type { ToneType } from "@xco-agency/corex-ui";

export type IntegrationCategoryType =
  | "all"
  | "marketing"
  | "support"
  | "analytics"
  | "webhooks";

export type IntegrationStatusType = "connected" | "disconnected" | "error";

export type IntegrationItemType = {
  id: string;
  name: string;
  description: string;
  category: "marketing" | "support" | "analytics" | "webhooks";
  status: IntegrationStatusType;
  syncEnabled: boolean;
  iconTone: "success" | "neutral" | "subdued" | "caution" | "info" | "critical";
  lastSyncedAt?: string;
  apiKey?: string;
  webhookUrl?: string;
};

export type WebhookLogItemType = {
  id: string;
  topic: string;
  status: "success" | "failed";
  statusCode: number;
  timestamp: string;
  durationMs: number;
};

export type IntegrationCategoryTabsPropsType = {
  categories: { id: IntegrationCategoryType; label: string; count: number }[];
  selectedCategory: IntegrationCategoryType;
  onSelectCategory: (category: IntegrationCategoryType) => void;
};

export type IntegrationCardPropsType = {
  integration: IntegrationItemType;
  onToggleSync: (id: string, enabled: boolean) => void;
  onConfigure: (integration: IntegrationItemType) => void;
};

export type IntegrationConfigModalPropsType = {
  open: boolean;
  integration: IntegrationItemType | null;
  onClose: () => void;
  onSave: (id: string, config: { apiKey?: string; webhookUrl?: string }) => void;
  onTestConnection: (id: string) => Promise<boolean>;
};

export type WebhookLogCardPropsType = {
  logs: WebhookLogItemType[];
  onRefresh: () => void;
};
